MEMORY_C = """/*
 * Memory allocator for TinyGL on the StopWatch (see tools/tinygl_patch.py).
 * Allocations of 192 bytes or more go to PSRAM on the board: the z-buffer,
 * display list buffers and context state are large, and the internal heap is
 * 325 KB. Smaller ones stay in fast internal RAM.
 */

#include "zgl.h"
#include <string.h>
#ifdef ESP_PLATFORM
#include <esp_heap_caps.h>
#endif

void gl_free(void* p) { free(p); }

void* gl_malloc(GLint size) {
#ifdef ESP_PLATFORM
	if (size >= 192) return heap_caps_malloc(size, MALLOC_CAP_SPIRAM);
#endif
	return malloc(size);
}

void* gl_zalloc(GLint size) {
	void* p = gl_malloc(size);
	if (p) memset(p, 0, size);
	return p;
}

/* For state read on every vertex (the matrix stacks): internal RAM when
 * built with GL_INTERNAL_MATRICES (issue #43), PSRAM by size otherwise. */
void* gl_zalloc_hot(GLint size) {
#if defined(ESP_PLATFORM) && defined(GL_INTERNAL_MATRICES)
	void* p = heap_caps_calloc(1, size, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
	if (p) return p;
#endif
	return gl_zalloc(size);
}
"""

